"use client";

import { Checkbox as CheckboxPrimitive } from "@base-ui/react/checkbox";
import { Icon } from "@iconify/react";

import { cn } from "@/lib/utils";
import { controlChecked, focusRing } from "./_shared";

type WithClassName<P> = Omit<P, "className"> & { className?: string };

/**
 * Paddock Checkbox: an empty box is a small white tile with a 1px cool border.
 * Checked or mixed, it fills with the primary Button's teal, so a ticked box
 * and the button read as one material. Base UI owns the checked state, so a
 * controlled parent passes `checked` straight through.
 */
function Checkbox({
  className,
  indeterminate,
  ...props
}: WithClassName<CheckboxPrimitive.Root.Props>) {
  return (
    <CheckboxPrimitive.Root
      data-slot="checkbox"
      indeterminate={indeterminate}
      className={cn(
        "peer relative grid size-4.5 shrink-0 place-items-center rounded-xs border border-transparent",
        "bg-(--field) text-primary-foreground shadow-(--control-ring)",
        controlChecked,
        "data-[indeterminate]:bg-primary data-[indeterminate]:shadow-(--primary-face)",
        "transition-[box-shadow,background-color] duration-fast ease-out",
        "data-[unchecked]:hover:shadow-(--control-lift)",
        focusRing,
        "data-[disabled]:cursor-not-allowed data-[disabled]:opacity-50",
        className,
      )}
      {...props}
    >
      <CheckboxPrimitive.Indicator
        data-slot="checkbox-indicator"
        className="size-full flex items-center justify-center text-current"
      >
        <Icon
          icon={indeterminate ? "mingcute:minimize-line" : "mingcute:check-line"}
          className="size-3"
          aria-hidden="true"
        />
      </CheckboxPrimitive.Indicator>
    </CheckboxPrimitive.Root>
  );
}
Checkbox.displayName = "Checkbox";

export { Checkbox };
